new:
# Admin roles alone no longer authorize API access on recent Keycloak.
for scope in kc("GET", "/client-scopes") or []:
    if scope.get("name") == "kc-admin-api":
        kc("PUT", f"/clients/{client['id']}/default-client-scopes/{scope['id']}")
account = kc("GET", f"/clients/{client['id']}/service-account-user")

{{- $customHost := .Values.credentialProxy.customInferenceHost | default "" -}}
{{- if $customHost -}}
  {{- if not (regexMatch "^[a-zA-Z0-9]([a-zA-Z0-9.-]*[a-zA-Z0-9])?$" $customHost) -}}
    {{- fail "credentialProxy.customInferenceHost must be a hostname" -}}
  {{- end -}}
  {{- if not (has $customHost (include "openshell-sandbox.egressHosts" . | fromJsonArray)) -}}
    {{- fail "credentialProxy.customInferenceHost must also be allowed by egress" -}}
  {{- end -}}
  {{- $_ := set $profiles "custom-inference" (list $customHost) -}}
{{- end -}}
{{- if hasKey $profiles "nvidia" -}}{{- $_ := set $profiles "build" (index $profiles "nvidia") -}}{{- end -}}

